import{_ as t,c as d,o,ah as c}from"./chunks/framework.BaqsfJuc.js";const m=JSON.parse('{"title":"Sideband Relay Protocol State Machine","description":"","frontmatter":{},"headers":[],"relativePath":"specs/secure-relay-protocol-state-machine.md","filePath":"specs/secure-relay-protocol-state-machine.md","lastUpdated":0}'),n={name:"specs/secure-relay-protocol-state-machine.md"};function a(r,e,s,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="sideband-relay-protocol-state-machine" tabindex="-1">Sideband Relay Protocol State Machine <a class="header-anchor" href="#sideband-relay-protocol-state-machine" aria-label="Permalink to “Sideband Relay Protocol State Machine”">​</a></h1><p>Concise state models for Client, Daemon, and Relay sessions. Intended to complement <code>secure-relay-protocol.md</code> with implementer-facing control flow.</p><h2 id="notation" tabindex="-1">Notation <a class="header-anchor" href="#notation" aria-label="Permalink to “Notation”">​</a></h2><ul><li>Event names are in <code>code</code> format.</li><li>Transitions list the next state and key requirements.</li><li>Error transitions terminate the session unless otherwise noted.</li></ul><h2 id="client-ui" tabindex="-1">Client (UI) <a class="header-anchor" href="#client-ui" aria-label="Permalink to “Client (UI)”">​</a></h2><p>States focus on a single daemon connection.</p><table tabindex="0"><thead><tr><th>State</th><th>Event</th><th>Next</th><th>Notes</th></tr></thead><tbody><tr><td><code>Idle</code></td><td><code>connect</code></td><td><code>Connecting</code></td><td>Open WebSocket to relay with user session.</td></tr><tr><td><code>Connecting</code></td><td><code>ws_open</code></td><td><code>Handshaking</code></td><td>Send <code>handshake.init</code> with client ephemeral key.</td></tr><tr><td><code>Connecting</code></td><td><code>ws_error</code></td><td><code>Closed</code></td><td>Surface transport error.</td></tr><tr><td><code>Handshaking</code></td><td><code>handshake.accept</code></td><td><code>Active</code></td><td>Verify Ed25519 signature using pinned identity key; derive session keys.</td></tr><tr><td><code>Handshaking</code></td><td><code>identity_key_changed</code></td><td><code>Closed</code></td><td>MUST abort; require explicit user confirmation to accept new key.</td></tr><tr><td><code>Handshaking</code></td><td><code>handshake_failed</code></td><td><code>Closed</code></td><td>Abort; discard ephemeral key material.</td></tr><tr><td><code>Active</code></td><td><code>daemon_disconnect</code></td><td><code>Paused</code></td><td>Keep WebSocket open; suspend encrypted sends.</td></tr><tr><td><code>Active</code></td><td><code>ws_close</code></td><td><code>Reconnecting</code></td><td>Client reconnect always requires full handshake.</td></tr><tr><td><code>Paused</code></td><td><code>daemon_reconnect_within_grace</code></td><td><code>Active</code></td><td>Resume with same session keys and sequence state.</td></tr><tr><td><code>Paused</code></td><td><code>relay_session_lost</code></td><td><code>Reconnecting</code></td><td>Trigger full handshake (new ephemeral keys).</td></tr><tr><td><code>Reconnecting</code></td><td><code>ws_open</code></td><td><code>Handshaking</code></td><td>Full handshake required.</td></tr><tr><td><code>Reconnecting</code></td><td><code>ws_error</code></td><td><code>Closed</code></td><td>Surface transport error.</td></tr><tr><td><code>Active</code></td><td><code>close</code></td><td><code>Closed</code></td><td>User-initiated disconnect.</td></tr></tbody></table><h2 id="daemon-agent" tabindex="-1">Daemon (Agent) <a class="header-anchor" href="#daemon-agent" aria-label="Permalink to “Daemon (Agent)”">​</a></h2><p>States focus on a single client session; daemons may have many in parallel.</p><table tabindex="0"><thead><tr><th>State</th><th>Event</th><th>Next</th><th>Notes</th></tr></thead><tbody><tr><td><code>Idle</code></td><td><code>register</code></td><td><code>Registered</code></td><td>Create identity keypair; register public key with relay.</td></tr><tr><td><code>Registered</code></td><td><code>connect</code></td><td><code>Connected</code></td><td>Open persistent WebSocket to relay with API key.</td></tr><tr><td><code>Connected</code></td><td><code>handshake.init</code></td><td><code>Handshaking</code></td><td>Generate ephemeral X25519 and sign with identity key.</td></tr><tr><td><code>Handshaking</code></td><td><code>handshake.accept_sent</code></td><td><code>Active</code></td><td>Derive session keys; init sequence state.</td></tr><tr><td><code>Active</code></td><td><code>client_disconnect</code></td><td><code>Idle</code></td><td>Per-session cleanup only.</td></tr><tr><td><code>Active</code></td><td><code>ws_close</code></td><td><code>Reconnecting</code></td><td>Attempt reconnect using same API key.</td></tr><tr><td><code>Reconnecting</code></td><td><code>ws_open_within_grace</code></td><td><code>Active</code></td><td>Resume per-session keys and sequence state only if still in memory; otherwise require full handshake.</td></tr><tr><td><code>Reconnecting</code></td><td><code>ws_open_after_grace</code></td><td><code>Connected</code></td><td>Start new sessions; old session state is dropped.</td></tr><tr><td><code>Active</code></td><td><code>sequence_state_lost</code></td><td><code>Handshaking</code></td><td>MUST force full handshake before sending encrypted data.</td></tr><tr><td><code>Connected</code></td><td><code>close</code></td><td><code>Closed</code></td><td>Tear down relay connection.</td></tr></tbody></table><h2 id="relay-per-session-pair" tabindex="-1">Relay (Per-Session Pair) <a class="header-anchor" href="#relay-per-session-pair" aria-label="Permalink to “Relay (Per-Session Pair)”">​</a></h2><p>A relay tracks the pairing between one client connection and one daemon connection.</p><table tabindex="0"><thead><tr><th>State</th><th>Event</th><th>Next</th><th>Notes</th></tr></thead><tbody><tr><td><code>None</code></td><td><code>client_ws_open</code></td><td><code>ClientOnly</code></td><td>Authenticate session; provide daemon list and identity key.</td></tr><tr><td><code>None</code></td><td><code>daemon_ws_open</code></td><td><code>DaemonOnly</code></td><td>Authenticate API key; mark daemon online.</td></tr><tr><td><code>ClientOnly</code></td><td><code>daemon_ws_open</code></td><td><code>Paired</code></td><td>Bind client to daemon; forward handshake messages.</td></tr><tr><td><code>DaemonOnly</code></td><td><code>client_ws_open</code></td><td><code>Paired</code></td><td>Bind client to daemon; forward handshake messages.</td></tr><tr><td><code>Paired</code></td><td><code>daemon_disconnect</code></td><td><code>Paused</code></td><td>Keep client socket open; pause encrypted traffic.</td></tr><tr><td><code>Paused</code></td><td><code>daemon_reconnect_within_grace</code></td><td><code>Paired</code></td><td>Resume routing with existing session state.</td></tr><tr><td><code>Paused</code></td><td><code>grace_expired</code></td><td><code>Closed</code></td><td>Tear down pairing; client must re-handshake.</td></tr><tr><td><code>Paired</code></td><td><code>client_disconnect</code></td><td><code>Closed</code></td><td>Tear down pairing; daemon session state may be retained for other clients.</td></tr></tbody></table><h2 id="required-invariants" tabindex="-1">Required Invariants <a class="header-anchor" href="#required-invariants" aria-label="Permalink to “Required Invariants”">​</a></h2><ul><li>No encrypted traffic before <code>Active</code> is reached.</li><li>A resumed session MUST reuse the same session keys and sequence state.</li><li>If sequence state is lost, a full handshake is REQUIRED before resuming encrypted traffic.</li><li>If the daemon process restarts or loses volatile memory, it MUST NOT resume a session and MUST require a full handshake.</li></ul>',15)])])}const u=t(n,[["render",a]]);export{m as __pageData,u as default};
